ReadOnlyConnectionAsyncWaiter::ReadOnlyConnectionAsyncWaiter(
    ReadOnlyConnection* proxy) : proxy_(proxy) {}

ReadOnlyConnectionAsyncWaiter::~ReadOnlyConnectionAsyncWaiter() = default;


void ReadOnlyConnectionAsyncWaiter::RunReadSequence(
    int32_t count, int32_t* out_successful_reads) {
  base::RunLoop loop;
  proxy_->RunReadSequence(
      std::move(count),
      base::BindOnce(
          [](base::RunLoop* loop,
             int32_t* out_successful_reads
,
             int32_t successful_reads) {*out_successful_reads = std::move(successful_reads);
            loop->Quit();
          },
          &loop,
          out_successful_reads));
  loop.Run();
}

int32_t ReadOnlyConnectionAsyncWaiter::RunReadSequence(
    int32_t count) {
  int32_t async_wait_result;
  RunReadSequence(std::move(count),&async_wait_result);
  return async_wait_result;
}

void ReadOnlyConnectionAsyncWaiter::CloseDatabase(
    std::vector<int32_t>* out_errors) {
  base::RunLoop loop;
  proxy_->CloseDatabase(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<int32_t>* out_errors
,
             const std::vector<int32_t>& errors) {*out_errors = std::move(errors);
            loop->Quit();
          },
          &loop,
          out_errors));
  loop.Run();
}

std::vector<int32_t> ReadOnlyConnectionAsyncWaiter::CloseDatabase(
    ) {
  std::vector<int32_t> async_wait_result;
  CloseDatabase(&async_wait_result);
  return async_wait_result;
}




